function validate([original, bounds]) {
  const n = original.length;
  if (n < 2 || n > 1e5) return 'original needs 2 to 10^5 values.';
  if (bounds.length !== n) return 'bounds needs exactly one pair for each value of original.';
  if (original.some(v => v < 1 || v > 1e9)) return 'Each original value is between 1 and 10^9.';
  if (bounds.some(b => b.length !== 2 || b[0] < 1 || b[0] > b[1] || b[1] > 1e9)) return 'Each bound is a pair [u, v] with 1 <= u <= v <= 10^9.';
  return null;
}

