function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 2 + Math.floor(rand() * 5);
  const top = large ? 1e9 : 20;
  const between = (a, b) => a + Math.floor(rand() * (b - a + 1));
  const original = Array.from({ length: n }, () => between(1, top / 2));
  // A hidden copy: original moved by a shift that keeps every value inside [1, top].
  let lowest = original[0], highest = original[0];
  for (const value of original) { lowest = Math.min(lowest, value); highest = Math.max(highest, value); }
  const shift = between(1 - lowest, top - highest);
  const slack = large ? between(0, 10 ** between(0, 8)) : between(0, 6);
  // Usually the bounds hug the hidden copy; sometimes a few random bounds may rule every copy out.
  const noise = rand() < 0.5 ? 0 : large ? 0.002 : 0.3;
  const bounds = original.map(value => {
    if (rand() < noise) {
      const u = between(1, top);
      return [u, between(u, top)];
    }
    const target = value + shift;
    return [between(Math.max(1, target - slack), target), between(target, Math.min(top, target + slack))];
  });
  return [original, bounds];
}
